questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: the unknown frequency is always after the median class, so it changes n but not CF or F; every median terminates at 1 d.p. and solves back to x. Source: original. */
P: [[[15,12,8,6,4,3],5,27],[[3,15,10,8,7,4],6,35],[[11,16,14,12,4,4],6,32],[[3,6,7,10,8,7],5,44],[[5,12,10,10,8,3],5,73/2],[[4,5,10,10,14,9],6,93/2],[[10,12,14,11,8,3],6,69/2],[[6,12,13,15,12,7],6,81/2],[[5,8,14,6,4,3],5,69/2],[[3,10,16,10,6,5],6,37]];
ix: 1+rand(10);
f: P[ix][1];
jx: P[ix][2];
med: P[ix][3];
xv: f[jx];
w: 10;
L1: 19/2;
cf: makelist(sum(f[i],i,1,t),t,1,length(f));
n: last(cf);
lcb: makelist(L1+(t-1)*w,t,1,length(f));
cb(p) := 1+length(sublist(cf,lambda([c],is(c<p))));
cfb(k) := if k=1 then 0 else cf[k-1];
gq(p) := lcb[cb(p)] + (p-cfb(cb(p)))/f[cb(p)]*w;
lo: makelist(10*t,t,1,6);
hi: makelist(10*t+9,t,1,6);
n0: n-xv;
km: cb(n/2);
Lm: lcb[km]; CFm: cfb(km); Fm: f[km];
medd: exd(med);
/* the equation: med = Lm + ((n0+x)/2 - CFm)/Fm*10 */
half: CFm+(med-Lm)*Fm/10;
/* diagnostics */
xn1: xv-1;
/* test values */
xo: xv+2;

feedbackvariables.text:
fa: makelist(if k=jx then ans1 else f[k],k,1,6);
cfa: makelist(sum(fa[i],i,1,t),t,1,6);
pa: cfa[6]/2;
ka: 1+length(sublist(cfa,lambda([c],is(c<pa))));
mchk: if is(ans1>=0) and is(ka<=6) then 19/2+10*(ka-1)+(pa-(if ka=1 then 0 else cfa[ka-1]))/fa[ka]*10 else -1;
